import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Release process","description":"","frontmatter":{},"headers":[],"relativePath":"contribute/release.md","filePath":"contribute/release.md","lastUpdated":1792860039000}'),i={name:"contribute/release.md"};function r(n,e,h,l,d,c){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="release-process" tabindex="-1">Release process <a class="header-anchor" href="#release-process" aria-label="Permalink to &quot;Release process&quot;">​</a></h1><p>This page describes how a MeetCue release is made: from bumping the version to the updated Scoop manifest.</p><h2 id="prepare" tabindex="-1">Prepare <a class="header-anchor" href="#prepare" aria-label="Permalink to &quot;Prepare&quot;">​</a></h2><ol><li>Make sure CI is green on the default branch.</li><li>Check prices in <code>crates/core/data/pricing.json</code> against the providers&#39; pricing pages and update the <code>verified</code> dates and <code>updated</code>. The app downloads this file from the documentation site, so a price fix only needs a push to the default branch, not a release.</li><li>Run the <a href="/meetcue/test-checklist">hardware test checklist</a> on a Windows computer with a build from the default branch.</li><li>Move the <strong>Unreleased</strong> entries in both <a href="/meetcue/reference/changelog">changelogs</a> under the new version heading.</li></ol><h2 id="bump-the-version" tabindex="-1">Bump the version <a class="header-anchor" href="#bump-the-version" aria-label="Permalink to &quot;Bump the version&quot;">​</a></h2><p>The version lives only in the root <code>Cargo.toml</code> under <code>[workspace.package]</code>. Also update <code>package.json</code>, <code>app/ui/package.json</code> and <code>docs/package.json</code> to the same value; <code>npm run check:versions</code> checks that they agree. <code>tauri.conf.json</code> takes the version from Cargo.</p><h2 id="tag" tabindex="-1">Tag <a class="header-anchor" href="#tag" aria-label="Permalink to &quot;Tag&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.0</span></span></code></pre></div><h2 id="what-the-release-workflow-does" tabindex="-1">What the release workflow does <a class="header-anchor" href="#what-the-release-workflow-does" aria-label="Permalink to &quot;What the release workflow does&quot;">​</a></h2><p>Pushing a <code>v*</code> tag runs <code>.github/workflows/release.yml</code> on Windows:</p><ol><li>Builds <code>MeetCue.exe</code> with the Tauri CLI, without an installer.</li><li>Packs <code>MeetCue.exe</code>, <code>LICENSE</code> and the README files into <code>meetcue-win-x64.zip</code> and computes its SHA-256 hash.</li><li>Creates the GitHub release with the zip and generated notes.</li><li>Updates <code>bucket/meetcue.json</code> with the new version, URL and hash, and commits it to the default branch as the identity in the repository variables <code>GIT_NAME</code> and <code>GIT_EMAIL</code>.</li><li>Installs Scoop on the runner, installs MeetCue from the updated manifest and checks that <code>MeetCue.exe --version</code> prints the new version.</li></ol><p>The hash is only ever computed and committed by the workflow, in the same run that uploads the zip. Never replace a release asset by hand; publish a new version instead.</p><h2 id="after-the-release" tabindex="-1">After the release <a class="header-anchor" href="#after-the-release" aria-label="Permalink to &quot;After the release&quot;">​</a></h2><ol><li>Check that <code>scoop update meetcue</code> picks up the new version on a Windows computer.</li><li>Check that the documentation site shows the new changelog.</li></ol><h2 id="repository-settings" tabindex="-1">Repository settings <a class="header-anchor" href="#repository-settings" aria-label="Permalink to &quot;Repository settings&quot;">​</a></h2><p>These are set once:</p><ul><li><strong>Settings › Pages</strong>: source is the <code>gh-pages</code> branch. The docs workflow publishes there on every change to <code>docs/</code> or <code>errors.json</code> on the default branch.</li><li><strong>Settings › Secrets and variables › Actions › Variables</strong>: <code>GIT_NAME</code> and <code>GIT_EMAIL</code> for commits made by workflows.</li><li>The repository must be public, or Scoop can&#39;t download release assets.</li></ul>`,17)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
